{
  "$schema": "https://opencode.ai/config.json",
  "default_agent": "orchestrator",
  "experimental": {
    "todo": true
  },
  "plugins": [
    {
      "package": "./plugins/free-model-filter",
      "options": {
        "freeOnly": false,
        "freeMatch": ":free"
      }
    },
    {
      "package": "./plugins/coding-model-filter",
      "options": {
        "requireTools": true
      }
    },
    {
      "package": "./plugins/context-window-filter",
      "options": {
        "minContext": 131072
      }
    },
    {
      "package": "./plugins/auto-model-switch",
      "options": {
        "maxRetries": 1,
        "pinDefault": true,
        "annotate": true
      }
    }
  ]
}

import { Plugin } from '@opencode/plugin';

type ModelRef = { providerID: string; modelID: string };

const normalize = (m: any): ModelRef | undefined => {
  if (!m) return undefined;
  const providerID = m.providerID ?? m.provider;
  const modelID = m.modelID ?? m.id;
  if (!providerID || !modelID) return undefined;
  return { providerID, modelID };
};

const contextOf = (m: any): number =>
  typeof m?.limit?.context === 'number' ? m.limit.context : 0;
const outputOf = (m: any): number =>
  typeof m?.limit?.output === 'number' ? m.limit.output : 0;

// Ranking balances two very different failure costs:
//
//   small context  -> the conversation dies mid-task and you restart (hard failure)
//   generic model  -> slightly worse answers, nothing breaks   (soft cost)
//
// So context leads and coding-specialisation only breaks ties *within* a context
// tier. Both signals are normalised to 0..1 before mixing.
//
// `capabilities.tools` is deliberately NOT a coding signal: the filter plugins
// already guarantee it for every surviving model, so it would be a constant that
// carries no ranking information while diluting the real ones.
const DEFAULT_W_CONTEXT = 0.7;

// Context is scored per *tier* rather than continuously. Continuous log scaling
// silently demotes every real model to a narrow band (a 256K vs a 1M window are
// only ~0.5 apart after scaling), which lets a keyword match overturn a 4x
// difference in window. Tiers make "bigger window first" an actual guarantee.
const CONTEXT_TIERS = [2_000_000, 1_000_000, 524_288, 262_144, 131_072];

// Within a context tier, a coding-specialised name outweighs the reasoning flag:
// naming a model after code is a far stronger signal than raw metadata carries.
const CODE_NAME_SHARE = 0.65;
const REASONING_SHARE = 0.35;

const contextScore = (m: any): number => {
  const c = contextOf(m);
  if (c <= 0) return 0;
  for (let i = 0; i < CONTEXT_TIERS.length; i++) {
    if (c >= CONTEXT_TIERS[i]) return 1 - i / CONTEXT_TIERS.length;
  }
  return 0;
};

const codingScore = (m: any): number => {
  const text = `${m?.id ?? ''} ${m?.name ?? ''}`.toLowerCase();
  let s = 0;
  if (/(code|coder|coding|program)/.test(text)) s += CODE_NAME_SHARE;
  if (m?.capabilities?.reasoning === true) s += REASONING_SHARE;
  return Math.min(1, s);
};

const totalScore = (m: any, wc: number, wk: number): number =>
  wc * contextScore(m) + wk * codingScore(m);

const compareByCapability = (
  a: any,
  b: any,
  wc: number,
  wk: number,
): number => {
  const byScore = totalScore(b, wc, wk) - totalScore(a, wc, wk);
  if (byScore !== 0) return byScore;
  const byOutput = outputOf(b) - outputOf(a);
  if (byOutput !== 0) return byOutput;
  return String(a?.id ?? '').localeCompare(String(b?.id ?? ''));
};

const formatSize = (n: number): string => {
  if (n >= 1_000_000)
    return `${(n / 1_000_000).toFixed(n % 1_000_000 === 0 ? 0 : 1)}M`;
  if (n >= 1_000) return `${Math.round(n / 1_000)}K`;
  return `${n}`;
};

const annotated = /^#\d+ [^·]+· /;

const FAILED_EVENTS = new Set([
  'session.step.failed',
  'session.execution.failed',
]);
const MODEL_SELECTED = 'session.model.selected';

// Same failure is emitted twice (step + execution); count it once.
const DUPLICATE_WINDOW_MS = 5000;

const dataOf = (e: any): any => e?.data ?? e?.properties ?? {};
const sessionOf = (e: any): string | undefined => dataOf(e).sessionID;

export default Plugin.define({
  id: 'auto-model-switch',
  async setup(ctx) {
    const maxRetries =
      typeof ctx.options?.maxRetries === 'number' ? ctx.options.maxRetries : 1;
    const pinDefault = ctx.options?.pinDefault !== false;
    const annotate = ctx.options?.annotate !== false;

    const wContext =
      typeof ctx.options?.contextWeight === 'number'
        ? ctx.options.contextWeight
        : DEFAULT_W_CONTEXT;
    const wCoding = 1 - wContext;
    const rank = (a: any, b: any) =>
      compareByCapability(a, b, wContext, wCoding);

    // Ranked view of the FILTERED model set (other plugins' removals applied).
    // Filled asynchronously; the transform below only reads it synchronously,
    // because editor mutations after an `await` are not committed.
    let rankedCache: any[] = [];
    let cacheKey = '';

    const refreshCache = async (): Promise<boolean> => {
      try {
        const r: any = await ctx.model.list();
        const arr = Array.isArray(r) ? r : Array.isArray(r?.data) ? r.data : [];
        const ranked = arr.slice().sort(rank);
        const key = ranked.map((m: any) => `${m.providerID}/${m.id}`).join('|');
        if (key === cacheKey) return false;
        cacheKey = key;
        rankedCache = ranked;
        return true;
      } catch {
        return false;
      }
    };

    const refreshAndReload = async () => {
      if (!(await refreshCache())) return;
      try {
        await ctx.model.reload();
      } catch {}
    };

    await ctx.model.transform((editor) => {
      const ranked = rankedCache;
      if (ranked.length === 0) return;

      if (pinDefault) {
        const best = normalize(ranked[0]);
        if (best) {
          const current = editor.default.get();
          if (
            !current ||
            current.providerID !== best.providerID ||
            current.modelID !== best.modelID
          ) {
            editor.default.set(best.providerID, best.modelID);
          }
        }
      }

      if (annotate) {
        ranked.forEach((m: any, i: number) => {
          const prefix = `#${i + 1} ${formatSize(contextOf(m))} · `;
          editor.update(m.providerID, m.id, (model: any) => {
            model.name = `${prefix}${String(model.name ?? '').replace(annotated, '')}`;
          });
        });
      }
    });

    const sessionModel = new Map<string, ModelRef>();
    const failures = new Map<string, number>();
    const lastFailure = new Map<string, { key: string; at: number }>();

    const listModels = async (): Promise<any[]> => {
      try {
        const r: any = await ctx.model.list();
        return Array.isArray(r) ? r : Array.isArray(r?.data) ? r.data : [];
      } catch {
        return [];
      }
    };

    const resolveCurrent = async (
      sessionID: string,
    ): Promise<ModelRef | undefined> => {
      const tracked = sessionModel.get(sessionID);
      if (tracked) return tracked;
      try {
        const s: any = await ctx.session.get({ sessionID });
        return normalize(s?.model) ?? normalize(s?.data?.model);
      } catch {
        return undefined;
      }
    };

    const switchTo = async (
      sessionID: string,
      next: ModelRef,
    ): Promise<boolean> => {
      try {
        await ctx.session.switchModel({
          sessionID,
          model: { providerID: next.providerID, id: next.modelID },
        });
        try {
          const s: any = await ctx.session.get({ sessionID });
          const msgs =
            s?.messages ??
            s?.data?.messages ??
            s?.turns ??
            s?.data?.turns ??
            s?.history ??
            s?.data?.history;
          if (Array.isArray(msgs) && msgs.length > 0) {
            const lastUser = [...msgs]
              .reverse()
              .find(
                (m: any) =>
                  m?.role === 'user' ||
                  m?.role === 'human' ||
                  m?.kind === 'user' ||
                  (m?.content ?? m?.text ?? '').length > 0,
              );
            const payload =
              lastUser?.content ??
              lastUser?.text ??
              lastUser?.message ??
              lastUser;
            const sessionApi = ctx.session as any;
            if (typeof sessionApi?.send === 'function' && payload) {
              await sessionApi.send({ sessionID, message: payload });
            } else if (typeof sessionApi?.submit === 'function' && payload) {
              await sessionApi.submit({ sessionID, message: payload });
            } else if (typeof sessionApi?.resubmit === 'function' && payload) {
              await sessionApi.resubmit({ sessionID, message: payload });
            } else if (typeof sessionApi?.retryTurn === 'function') {
              await sessionApi.retryTurn({ sessionID });
            }
          }
        } catch {}
        return true;
      } catch {
        return false;
      }
    };

    // A model that returns a non-2xx status is unusable; move to the next one
    // down the ranking. No error-message parsing is involved.
    const onFailure = async (e: any) => {
      const data = dataOf(e);
      const err = data.error ?? {};

      const status = typeof err.status === 'number' ? err.status : undefined;
      if (status !== undefined && status >= 200 && status < 300) return;
      if (/abort/i.test(String(err.type ?? ''))) return;

      const sid = sessionOf(e);
      if (!sid) return;

      const signature = `${err.type ?? ''}|${status ?? ''}|${String(err.message ?? '').slice(0, 80)}`;
      const previous = lastFailure.get(sid);
      if (
        previous &&
        previous.key === signature &&
        Date.now() - previous.at < DUPLICATE_WINDOW_MS
      )
        return;
      lastFailure.set(sid, { key: signature, at: Date.now() });

      const current = await resolveCurrent(sid);
      if (!current) return;

      const key = `${sid}|${current.providerID}/${current.modelID}`;
      const count = (failures.get(key) ?? 0) + 1;
      failures.set(key, count);
      if (count < maxRetries) return;

      const ranked = rankedCache.length > 0 ? rankedCache : await listModels();
      const idx = ranked.findIndex(
        (p: any) =>
          p.providerID === current.providerID && p.modelID === current.modelID,
      );
      if (idx < 0 || idx + 1 >= ranked.length) return;

      const next = normalize(ranked[idx + 1]);
      if (!next) return;

      if (await switchTo(sid, next)) {
        failures.set(key, 0);
        lastFailure.delete(sid);
        sessionModel.set(sid, next);
      }
    };

    const controller = new AbortController();
    (async () => {
      try {
        for await (const event of ctx.event.subscribe({
          signal: controller.signal,
        })) {
          const e = event as any;
          try {
            const type = String(e?.type ?? '');
            const data = dataOf(e);

            if (type === 'model.updated') {
              await refreshAndReload();
              continue;
            }

            if (type === MODEL_SELECTED && data.model) {
              const ref = normalize(data.model);
              if (ref && data.sessionID) sessionModel.set(data.sessionID, ref);
              continue;
            }

            if (!FAILED_EVENTS.has(type)) continue;
            await onFailure(e);
          } catch {
            // One bad event must never kill the subscription.
          }
        }
      } catch (err: any) {
        if (err?.name !== 'AbortError')
          console.error('[auto-model-switch] event stream ended:', err);
      }
    })();

    // Initial fill, plus delayed re-checks in case filters commit after setup.
    await refreshCache();
    for (const delay of [3000, 10000, 30000]) {
      setTimeout(() => refreshAndReload(), delay);
    }

    return () => controller.abort();
  },
});

import { Plugin } from '@opencode/plugin';

export default Plugin.define({
  id: 'coding-model-filter',
  async setup(ctx) {
    const requireTools = ctx.options?.requireTools !== false;

    await ctx.model.transform((editor) => {
      for (const m of editor.list()) {
        const isAvailable =
          m?.enabled !== false && (m?.status == null || m.status === 'active');
        const supportsTools = m?.capabilities?.tools === true;

        if (!isAvailable || (requireTools && !supportsTools)) {
          editor.remove(m.providerID, m.id);
        }
      }
    });
  },
});

import { Plugin } from '@opencode/plugin';

export default Plugin.define({
  id: 'context-window-filter',
  async setup(ctx) {
    const raw = ctx.options?.minContext;
    const minContext =
      typeof raw === 'number' && Number.isFinite(raw) && raw >= 0
        ? raw
        : 131072;

    await ctx.model.transform((editor) => {
      for (const m of editor.list()) {
        const context =
          typeof m?.limit?.context === 'number' ? m.limit.context : 0;
        if (context < minContext) editor.remove(m.providerID, m.id);
      }
    });
  },
});

import { Plugin } from '@opencode/plugin';

export default Plugin.define({
  id: 'free-model-filter',
  async setup(ctx) {
    const freeOnly = ctx.options?.freeOnly !== false;
    const freeMatch =
      typeof ctx.options?.freeMatch === 'string'
        ? ctx.options.freeMatch.toLowerCase()
        : ':free';

    const isFree = (m: any): boolean => {
      const id = String(m?.id ?? m?.modelID ?? '').toLowerCase();
      if (id.includes(freeMatch)) return true;
      const cost = m?.cost;
      if (Array.isArray(cost) && cost.length) {
        return cost.every(
          (c: any) =>
            c.input === 0 &&
            c.output === 0 &&
            (c.cache?.read ?? 0) === 0 &&
            (c.cache?.write ?? 0) === 0,
        );
      }
      return false;
    };

    await ctx.model.transform((editor) => {
      for (const m of editor.list()) {
        if (isFree(m) !== freeOnly) editor.remove(m.providerID, m.id);
      }
    });
  },
});

# LinkedIn post search

Reference for `linkedin-feed-jobs`. Every job title, location, hiring keyword and stack term comes from `job-hunter.config.json`. This file must never contain a hardcoded list of job titles, cities, regions or countries.

## 1. Entry

```
https://www.linkedin.com/search/results/content/?keywords=<query>&datePosted=<bucket>&sortBy=date_posted
```

- `keywords`: URL-encoded query.
- `datePosted`: `past-24h`, `past-week` or `past-month`.
- `common.sortBy=date_posted`.
- Open in the dedicated feed tab. Do not reuse the feed tab's scroll position.

After load, verify the page shows a date filter matching the bucket and `Sort by: Date posted`. If the URL parameters were dropped, set the same controls in the UI and verify again. If the controls are unavailable, record the limitation and fall back to the Recent feed pass.

## 2. Inputs from config

| Input | Config key | Use |
|---|---|---|
| Titles | `common.jobTitles.include` | Query terms and the hard title gate |
| Locations | `common.locations`, then `common.countries` | Query terms and the hard location gate |
| Extra location terms | `platforms.LinkedIn.feedJobs.locationTerms` | Appended only when non-empty |
| Hiring keywords | `platforms.LinkedIn.feedJobs.searchKeywords` | Query terms |
| Stack terms | `common.technicalKeywords.include` | Query terms and `Matched keywords` |
| Query cap | `platforms.LinkedIn.feedJobs.maxQueries` | Maximum queries per run |
| Page cap | `platforms.LinkedIn.feedJobs.maxPagesPerQuery` | Pages per query |

Read the values at run time. Never copy them into this file or into `SKILL.md`.

When `common.locations` is empty, the location terms are exactly the configured `common.countries` values. When `common.locations` is non-empty, use those values and do not add countries.

## 3. Query building

Normalize titles for query building only: lowercase, collapse whitespace, replace `-`/`_` with a space, fold joined and separated spellings, strip a leading seniority prefix, deduplicate. Never change the title used for matching.

Build in this order, stop at `maxQueries`:

1. **Title queries** — one per base title, up to 6: `<hiring keyword> "<base title>" <location term>`
2. **Stack queries** — one per location term, up to 4: `<hiring keyword> (<stack term> OR <stack term>) <location term>`
3. **Broad query** — one: `(<hiring keywords>) (<base titles>) (<location terms>)`

Rules:

- Quote multi-word titles. Keep each query under about 300 characters.
- Rotate location terms across queries; do not repeat the same term in every query.
- Use only configured hiring keywords, titles, stack terms and location terms.
- Never add a city, country, company, salary, seniority or easy-apply filter that is not in the config.
- Prefer plain keyword queries over boolean ones. If a boolean query returns zero cards or an error, retry it once without parentheses and `OR`.
- Use the local-language spelling of a configured location only when it denotes the same place as the configured value.

## 4. Time bucket

| feed window (`feedJobs.lookbackHours`, else `common.lookbackHours`) | `datePosted` |
|---|---|
| ≤ 24 | `past-24h` |
| ≤ 168 | `past-week` |
| ≤ 720 | `past-month` |
| > 720 | omit the parameter |

Pick the closest bucket that fully covers the window, never a narrower one. Then filter each card by its relative time:

```js
const ageHours = (label) => {
  const m = (label || '').trim().match(/^(\d+)\s*([mhdw])$/i);
  if (!m) return null;
  const n = Number(m[1]);
  return { m: n / 60, h: n, d: n * 24, w: n * 168 }[m[2].toLowerCase()];
};
```

`1d` covers 24–48 hours. When the feed window is 24 hours, include `1d` as the boundary and mark `24h boundary`.

## 5. Collect

Expand truncated posts first:

```js
const expand = async () => page.evaluate(() => {
  let n = 0;
  document.querySelectorAll('button').forEach(b => {
    const t = (b.innerText || '').trim();
    if (/^(…|...)\s*more$/i.test(t) || t.toLowerCase() === 'see more') {
      try { b.click(); n++; } catch (e) {}
    }
  });
  return n;
});
```

Collect cards from the results container. Cover both the search list and embedded feed cards:

```js
const collect = async () => page.evaluate(() => {
  const seen = new Set();
  const out = [];
  const nodes = document.querySelectorAll(
    'div[role="listitem"], div.feed-shared-update-v2, [data-urn*="urn:li:activity"]'
  );
  nodes.forEach(el => {
    const text = (el.innerText || '').trim();
    if (!text) return;
    const urn = el.getAttribute('data-urn') || el.getAttribute('componentkey') || '';
    const link = el.querySelector('a[href*="/feed/update/"], a[href*="urn:li:activity"]');
    const href = link ? link.href.split('?')[0] : '';
    const key = urn || href || text.slice(0, 120);
    if (seen.has(key)) return;
    seen.add(key);
    out.push({ key, text, href });
  });
  return out;
});
```

For each card record: text, author, relative time, permalink, hiring keywords seen, and the rendered location phrase if any. Deduplicate by activity URN, then by canonical permalink, then by the first 120 characters of text.

If the browser cannot expose `innerText` for a card, skip it and count it as unreadable; never guess its content.

## 6. Pagination

Advance with the results `Next` / `Show more results` control, otherwise scroll the results container (`.scaffold-finite-scroll__content`, then `#workspace`, then `window`).

Stop when any of these happens:

- `maxPagesPerQuery` pages are read;
- two consecutive screens add no new card;
- the next cards are older than the feed window;
- results repeat;
- a login wall, CAPTCHA or rate limit appears.

Keep a per-query count: pages opened, cards seen, new cards after dedupe, stop reason.

## 7. Permalink

1. Read the timestamp anchor's `href` when it matches `/feed/update/` or `urn:li:activity`; strip the query string.
2. Otherwise open the post's `Open control menu for post`, choose `Copy link to post`, and read the clipboard (`pbpaste` on macOS). Keep `https://lnkd.in/p/...` as-is.
3. Otherwise write `Link unavailable`.

Never assemble a URL from a URN, company name or title. Hide extension overlays before clicking a menu:

```js
await page.evaluate(() => {
  document.querySelectorAll('#interop-outlet, [data-testid="interop-shadowdom"]')
    .forEach(e => { e.style.display = 'none'; });
});
```

## 8. Recent feed supplement

When `platforms.LinkedIn.feedJobs.includeRecentFeed` is `true`, run one Recent-feed pass after the searches:

- Follow `.opencode/skills/linkedin-feed-review/references/feed-extraction.md` for opening, sorting, collecting and scrolling.
- Read at most `maxScreens` screens; stop after two screens with no post in the window.
- Do not apply `platforms.LinkedIn.feedReview.excludeTopics`; hiring posts are the target here.
- Merge results into the same dedupe set.

## 9. Limits and failures

- Never log in, solve a CAPTCHA or bypass an access control. Stop the affected query and record it in limitations.
- Stop the whole search after three consecutive blocked or empty queries and fall back to the Recent feed pass.
- Write large raw result sets to a temp file with `files.write` and read it in chunks.
- Search results are not proof a role is still open; validity is judged from the post text only.

# LinkedIn Recent feed extraction

Use this recipe for `linkedin-feed-review` and `linkedin-feed-jobs`. It matches the current LinkedIn feed DOM.

## 1. Open and sort

```js
await page.goto('https://www.linkedin.com/feed/', { waitUntil: 'domcontentloaded' });
await page.waitForTimeout(5000);

const sortBtn = page.locator('div[role="button"]').filter({ hasText: 'Sort by:' }).first();
await sortBtn.click();
await page.waitForTimeout(1200);
await page.getByText('Recent', { exact: true }).last().click();
await page.waitForTimeout(4000);
```

Verify the label says `Sort by: Recent`. If not, retry once.

## 2. Collect

Posts are `div[role="listitem"]` elements whose `componentkey` contains `update-card`. Do not read `div[role="list"]` direct children.

```js
const expand = async () => page.evaluate(() => {
  let n = 0;
  document.querySelectorAll('button').forEach(b => {
    const t = (b.innerText || '').trim();
    if (/^(…|...)\s*more$/i.test(t) || t.toLowerCase() === 'see more') {
      try { b.click(); n++; } catch (e) {}
    }
  });
  return n;
});

const collect = async () => page.evaluate(() =>
  Array.from(document.querySelectorAll('div[role="listitem"][componentkey*="update-card"]'))
    .map(e => ({ key: e.getAttribute('componentkey') || '', text: (e.innerText || '').trim() }))
);

const scroll = async () => page.evaluate(() => {
  const m = document.getElementById('workspace');
  if (m) { m.scrollBy(0, m.clientHeight * 0.9); return m.scrollTop; }
  window.scrollBy(0, 800);
  return window.scrollY;
});
```

Expand, collect, deduplicate by `componentkey`, scroll. Read at most 10 screens; stop after three screens with no post in the window. Write large results to a temp file with `files.write` and read it in chunks.

## 3. Hide click blockers

Hide extension overlays before clicking a post menu:

```js
await page.evaluate(() => {
  document.querySelectorAll('#interop-outlet, [data-testid="interop-shadowdom"]')
    .forEach(e => { e.style.display = 'none'; });
});
```

## 4. Copy a permalink

Do this only for selected posts.

1. Find the post by a unique text fragment.
2. Click `button[aria-label^="Open control menu for post"]`.
3. Click `Copy link to post` in the visible `[role="menu"]`.
4. Read the clipboard (`pbpaste` on macOS). If unavailable, write `Link unavailable`.

```js
const key = await page.evaluate((marker) => {
  const el = Array.from(document.querySelectorAll('div[role="listitem"][componentkey*="update-card"]'))
    .find(e => (e.innerText || '').includes(marker));
  if (!el) return null;
  el.scrollIntoView({ block: 'center' });
  return el.getAttribute('componentkey');
}, 'unique text fragment');

await page.locator(`[componentkey="${key}"] button[aria-label^="Open control menu for post"]`).first().click();
await page.waitForTimeout(900);
await page.locator('[role="menu"]').filter({ hasText: 'Copy link to post' }).last()
  .getByText('Copy link to post', { exact: true }).click();
```

The copied URL is usually `https://lnkd.in/p/...`. Keep it as-is.

## 5. Time window

LinkedIn shows `23h` then `1d`. `1d` covers 24–48 hours. With `common.lookbackHours` 24, include `1d` as the boundary and mark `24h boundary`.

## 6. Avoid

- Reading `div[role="list"] > *`.
- Scrolling `window` when `#workspace` exists.
- Re-navigating between screens.
- Opening profiles for discovery. Open a candidate profile once, read-only, only to confirm role and location.
- Clicking links inside posts.
